function pacer(commands){if(!Array.isArray(commands))throw"pacer: commands not given as an array";if(commands.length==0)return;if(typeof commands[0]=="function"){commands[0]();commands.shift();pacer(commands);return}if(!(Array.isArray(commands[0])&&commands[0].length>0&&commands[0][1]>0))throw"pacer: invalid command";if(commands[0][0]==="delay"){var delay=commands[0][1];commands.shift();setTimeout(function(){pacer(commands)},delay);return}if(typeof commands[0][0]!="function")throw"pacer: invalid command";if(commands[0][0]()===true){setTimeout(function(){pacer(commands)},commands[0][1]);return}commands.shift();pacer(commands)}
